final class SymbiosisTests {
    static void register(DeferredRegister<Consumer<GameTestHelper>> f){
        f.register("symbiosis_trial",()->SymbiosisTests::trial);f.register("symbiosis_unique",()->SymbiosisTests::unique);f.register("symbiosis_injury",()->SymbiosisTests::injury);f.register("symbiosis_capsule",()->SymbiosisTests::capsule);f.register("symbiosis_blocked",()->SymbiosisTests::blocked);f.register("symbiosis_progression",()->SymbiosisTests::progression);f.register("symbiosis_skills",()->SymbiosisTests::skills);f.register("symbiosis_menu",()->SymbiosisTests::menu);f.register("symbiosis_computer",()->SymbiosisTests::computer);f.register("symbiosis_biome",()->SymbiosisTests::biome);f.register("symbiosis_city",()->SymbiosisTests::city);f.register("symbiosis_shield",()->SymbiosisTests::shield);f.register("symbiosis_piston",()->SymbiosisTests::piston);f.register("symbiosis_dome",()->SymbiosisTests::dome);
    }
    static void check(GameTestHelper h,boolean ok,String s){h.assertTrue(ok,Component.literal(s));}
    static Shardling pet(ServerLevel w,BlockPos at){var pet=VestigeEntities.SHARDLING.get().create(w,EntitySpawnReason.EVENT);pet.setPos(Vec3.atBottomCenterOf(at));w.addFreshEntity(pet);return pet;}
    static Shardling owned(GameTestHelper h,ServerPlayer p,BlockPos at){var pet=pet(p.level(),at);pet.tame(p);check(h,pet.isOwnedBy(p),"Test fixture creates the one persisted bond");return pet;}
    static ItemStack capsule(ServerPlayer p){for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(FamiliarContent.CAPSULE.get()))return p.getInventory().getItem(i);return ItemStack.EMPTY;}
    static Shardling reload(ServerLevel w,Shardling pet){var o=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,w.registryAccess());pet.saveWithoutId(o);return (Shardling)EntityType.create(VestigeEntities.SHARDLING.get(),TagValueInput.create(ProblemReporter.DISCARDING,w.registryAccess(),o.buildResult()),w,EntitySpawnReason.LOAD).orElseThrow();}
    static void raise(Shardling pet,int level){while(pet.familiarLevel()<level)pet.awardExperience(100);}
    static void trial(GameTestHelper h){
        var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);var p=GameplayTests.player(h);p.setPos(Vec3.atBottomCenterOf(at.east(4)));var pet=pet(w,at);pet.releaseFor(p);float hp=p.getHealth();
        h.runAfterDelay(70,()->{check(h,p.getHealth()<hp,"The released subject physically attacks its challenger through native melee AI");pet.hurtServer(w,p.damageSources().playerAttack(p),1000);check(h,pet.downed()&&pet.isAlive()&&!pet.isRemoved(),"Lethal native damage leaves the subject injured, never dead");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(FamiliarContent.NUTRIENT.get(),2));pet.mobInteract(p,InteractionHand.MAIN_HAND);check(h,pet.isOwnedBy(p)&&pet.bondTicks()==60&&p.getMainHandItem().getCount()==1,"One hidden nutrient creates the unique bond and starts the sequence");
            h.runAfterDelay(65,()->{try{check(h,pet.available()&&!pet.downed()&&!pet.isOrderedToSit()&&pet.getHealth()==pet.getMaxHealth(),"The sequence restores the subject and enables following");}finally{pet.discard();GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();});});
    }
    static void unique(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var a=owned(h,p,h.absolutePos(new BlockPos(10,2,10)));var b=pet(w,a.blockPosition().east(2));var other=GameplayTests.player(h);
        try{b.releaseFor(p);b.hurtServer(w,p.damageSources().playerAttack(p),1000);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(FamiliarContent.NUTRIENT.get(),3));b.mobInteract(p,InteractionHand.MAIN_HAND);check(h,!b.isTame()&&p.getMainHandItem().getCount()==3,"A second downed subject cannot overwrite the existing bond or consume food");
            other.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(FamiliarContent.NUTRIENT.get(),2));a.setHealth(10);a.mobInteract(other,InteractionHand.MAIN_HAND);check(h,a.getHealth()==10&&other.getMainHandItem().getCount()==2,"Other players cannot heal or take ownership of this pet");
            var ledger=FamiliarLedger.get(w.getServer());ledger.snapshot(a);var restored=FamiliarLedger.CODEC.parse(NbtOps.INSTANCE,FamiliarLedger.CODEC.encodeStart(NbtOps.INSTANCE,ledger).getOrThrow()).getOrThrow();check(h,restored.owns(p.getUUID(),a.getUUID())&&!restored.claim(p,b),"SavedData codec persists the one-bond guard across a real serialization round trip");
        }finally{a.discard();b.discard();GameplayTests.cleanup(other);GameplayTests.cleanup(p);}h.succeed();}
    static void injury(GameTestHelper h){var p=GameplayTests.player(h);var pet=owned(h,p,h.absolutePos(new BlockPos(8,2,8)));var w=h.getLevel();
        try{raise(pet,8);int lv=pet.familiarLevel();pet.hurtServer(w,w.damageSources().genericKill(),1000);check(h,pet.downed()&&pet.isAlive()&&pet.getExperienceReward(w,p)==0&&!pet.available(),"An evolved companion survives lethal damage without loot or XP");check(h,!pet.hurtServer(w,w.damageSources().lava(),1000)&&!pet.canAttack(p),"A downed pet resists repeated hazards and has no combat AI");var restored=reload(w,pet);check(h,restored.downed()&&restored.isNoAi()&&restored.familiarLevel()==lv,"Native entity serialization preserves injury and levels");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(FamiliarContent.NUTRIENT.get(),2));pet.mobInteract(p,InteractionHand.MAIN_HAND);check(h,!pet.downed()&&!pet.isNoAi()&&pet.getHealth()==pet.getMaxHealth()&&pet.familiarLevel()==lv&&p.getMainHandItem().getCount()==1,"One crafted nutrient fully revives without erasing progression");pet.mobInteract(p,InteractionHand.MAIN_HAND);check(h,p.getMainHandItem().getCount()==1,"Feeding a healthy pet does not waste nourishment");
        }finally{pet.discard();GameplayTests.cleanup(p);}h.succeed();}
    static void capsule(GameTestHelper h){var p=GameplayTests.player(h);var foreign=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);p.setPos(Vec3.atBottomCenterOf(at));foreign.setPos(p.position());var pet=owned(h,p,at.east(2));var id=pet.getUUID();var ledger=FamiliarLedger.get(w.getServer());
        try{raise(pet,8);ledger.rename(p,"Écho-7");pet.hurtServer(w,w.damageSources().genericKill(),1000);p.setShiftKeyDown(true);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);pet.mobInteract(p,InteractionHand.MAIN_HAND);p.setShiftKeyDown(false);var item=capsule(p);check(h,pet.isRemoved()&&!item.isEmpty()&&ledger.record(p.getUUID()).getBooleanOr("Stored",false),"Shift interaction packs a downed creature into the actual inventory");var duplicate=item.copy();check(h,!ledger.deploy(foreign,duplicate,Vec3.atBottomCenterOf(at.west(3)))&&duplicate.getCount()==1,"A stolen or copied ticket cannot be deployed by another player");
            check(h,ledger.deploy(p,item,Vec3.atBottomCenterOf(at.west(3)))&&item.isEmpty(),"Owner deploys the actual capsule and consumes it, including in creative");var arrived=ledger.loaded(w.getServer(),p.getUUID());check(h,arrived!=null&&arrived.getUUID().equals(id)&&arrived.downed()&&arrived.familiarLevel()>=8&&arrived.getName().getString().equals("Écho-7"),"Transport preserves identity, evolution, name and injury");check(h,!ledger.deploy(p,duplicate,Vec3.atBottomCenterOf(at.south(4)))&&duplicate.getCount()==1,"Replaying the old ticket never duplicates the pet");arrived.discard();
        }finally{if(!pet.isRemoved())pet.discard();var active=ledger.loaded(w.getServer(),p.getUUID());if(active!=null)active.discard();GameplayTests.cleanup(foreign);GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    static void blocked(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);p.setPos(Vec3.atBottomCenterOf(at));var pet=owned(h,p,at.east(2));var ledger=FamiliarLedger.get(w.getServer());
        try{check(h,ledger.pack(p,pet),"Pet is safely packed");var item=capsule(p);var target=at.west(3);w.setBlock(target,Blocks.GOLD_BLOCK.defaultBlockState(),3);check(h,!ledger.deploy(p,item,Vec3.atBottomCenterOf(target))&&item.getCount()==1,"Solid obstruction rejects deployment without consuming the capsule");w.setBlock(target,Blocks.AIR.defaultBlockState(),3);w.setBlock(target.below(),Blocks.MAGMA_BLOCK.defaultBlockState(),3);check(h,!ledger.deploy(p,item,Vec3.atBottomCenterOf(target)),"Hazardous floors are rejected");check(h,ledger.record(p.getUUID()).getBooleanOr("Stored",false)&&ledger.loaded(w.getServer(),p.getUUID())==null,"Failed deployments keep the single pet safely stored");
        }finally{GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    static void progression(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);p.setPos(Vec3.atBottomCenterOf(at));var pet=owned(h,p,at.east(2));
        try{var zombie=EntityTypes.ZOMBIE.create(w,EntitySpawnReason.EVENT);zombie.setNoAi(true);zombie.setPos(Vec3.atBottomCenterOf(at.east(4)));w.addFreshEntity(zombie);zombie.hurtServer(w,p.damageSources().playerAttack(p),1000);check(h,pet.familiarXp()>0,"A real nearby owner victory awards independent companion XP");int xp=pet.familiarXp();var cow=EntityTypes.COW.create(w,EntitySpawnReason.EVENT);cow.setPos(zombie.position());w.addFreshEntity(cow);cow.hurtServer(w,p.damageSources().playerAttack(p),1000);check(h,pet.familiarXp()==xp,"Livestock kills cannot farm companion experience");raise(pet,8);check(h,pet.evolution()==1&&pet.getMaxHealth()==46&&pet.getAttributeValue(Attributes.SCALE)==1.3,"Level eight changes real health, scale and evolution");raise(pet,20);check(h,pet.evolution()==2&&pet.getMaxHealth()==78&&pet.getAttributeValue(Attributes.ATTACK_DAMAGE)>12&&pet.getAttributeValue(Attributes.SCALE)==1.65,"Level twenty produces a stronger, larger third form");pet.setHealth(37);var restored=reload(w,pet);check(h,restored.familiarLevel()==pet.familiarLevel()&&restored.familiarXp()==pet.familiarXp()&&restored.getHealth()==37&&restored.evolution()==2,"Native reload preserves XP, form and exact health without free healing");
        }finally{pet.discard();GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    static void skills(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);p.setPos(Vec3.atBottomCenterOf(at.west(2)));var pet=owned(h,p,at);raise(pet,12);pet.setNoAi(true);var zombie=EntityTypes.HUSK.create(w,EntitySpawnReason.EVENT);zombie.setNoAi(true);zombie.setPos(Vec3.atBottomCenterOf(at.east(2)));w.addFreshEntity(zombie);pet.setTarget(zombie);float hp=zombie.getHealth();p.hurtServer(w,w.damageSources().mobAttack(zombie),1);
        h.runAfterDelay(3,()->check(h,pet.pulseTicks()>0&&zombie.getHealth()==hp&&p.hasEffect(net.minecraft.world.effect.MobEffects.ABSORPTION),"Unlocked pulse telegraphs before damage; aegis protects the injured owner"));
        h.runAfterDelay(25,()->{try{check(h,zombie.getHealth()<hp&&pet.pulseTicks()==0,"Unlocked native pulse damages the hostile after its warning");}finally{pet.discard();zombie.discard();GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();});}
    static void menu(GameTestHelper h){var p=GameplayTests.player(h);var other=GameplayTests.player(h);var pet=owned(h,p,h.absolutePos(new BlockPos(8,2,8)));p.setPos(pet.position());var menu=new FamiliarMenu(31,p.getInventory(),p);var ledger=FamiliarLedger.get(p.level().getServer());
        try{check(h,!menu.clickMenuButton(other,0)&&!menu.rename(other,"Volé")&&!menu.clickMenuButton(p,1000),"Forged owner and action indices are rejected");check(h,!menu.rename(p," ")&&!menu.rename(p,"a".repeat(25))&&menu.rename(p,"Écho"),"Rename validation enforces a readable bounded player name");check(h,pet.getName().getString().equals("Écho")&&menu.clickMenuButton(p,0)&&pet.isOrderedToSit(),"The actual owner can rename and order the pet");check(h,menu.clickMenuButton(p,0)&&!pet.isOrderedToSit(),"The same menu resumes following");var old=p.position();p.setPos(old.add(20,0,0));check(h,!menu.clickMenuButton(p,1)&&!pet.isRemoved(),"Remote menu cannot remove or pack a distant pet");
        }finally{pet.discard();GameplayTests.cleanup(p);GameplayTests.cleanup(other);}h.succeed();}
    static void computer(GameTestHelper h){
        var w=FieldworkTests.vestige(h);var origin=new BlockPos(42000,100,42000);for(int x=origin.getX()>>4;x<=(origin.getX()+46)>>4;x++)for(int z=origin.getZ()>>4;z<=(origin.getZ()+46)>>4;z++)w.setChunkForced(x,z,true);
        var template=w.getStructureManager().get(Identifier.fromNamespaceAndPath("tnd","incubation_laboratory")).orElseThrow();template.placeInWorld(w,origin,origin,new StructurePlaceSettings(),w.getRandom(),2);var at=origin.offset(23,1,15);var p=FieldworkTests.player(h,w,at);w.waitForEntities(new ChunkPos(at.getX()>>4,at.getZ()>>4),0);var c=(IncubationComputerEntity)w.getBlockEntity(origin.offset(23,2,17));
        check(h,c.start(p)&&!c.start(p),"Physical computer begins one guarded decompression sequence");var copy=(IncubationComputerEntity)BlockEntity.loadStatic(c.getBlockPos(),c.getBlockState(),c.saveWithFullMetadata(w.registryAccess()),w.registryAccess());check(h,!copy.opened()&&copy.opening()==0,"Reload cancels unfinished incubation rather than releasing an unseen attacker");
        var chest=(ChestBlockEntity)w.getBlockEntity(origin.offset(36,1,38));chest.unpackLootTable(p);int food=0;for(int n=0;n<chest.getContainerSize();n++)if(chest.getItem(n).is(FamiliarContent.NUTRIENT.get()))food+=chest.getItem(n).getCount();check(h,food==6,"The real hidden native chest guarantees the six taming and healing nutrients");
        var walker=EntityTypes.ZOMBIE.create(w,EntitySpawnReason.EVENT);walker.setNoAi(true);walker.setPos(Vec3.atBottomCenterOf(at));walker.setOnGround(true);walker.getAttribute(Attributes.FOLLOW_RANGE).setBaseValue(128);w.addFreshEntity(walker);var nav=(net.minecraft.world.entity.ai.navigation.GroundPathNavigation)walker.getNavigation();nav.setRequiredPathLength(100);nav.setMaxVisitedNodesMultiplier(16);var path=nav.createPath(origin.offset(36,1,37),0);check(h,path!=null&&path.canReach(),"Hidden supplies are physically reachable without breaking any protected wall; end="+(path==null?"null":path.getEndNode()));walker.discard();
        h.runAfterDelay(86,()->{try{var subjects=w.getEntitiesOfClass(Shardling.class,new AABB(Vec3.atLowerCornerOf(origin),Vec3.atLowerCornerOf(origin.offset(47,27,47))));check(h,c.opened()&&subjects.size()==1&&subjects.getFirst().trial(),"Exactly one live defensive subject emerges from the chamber");check(h,!c.start(p),"The released subject cannot be duplicated through repeated interaction");for(var pet:subjects)pet.discard();}finally{GameplayTests.cleanup(p);for(int x=origin.getX()>>4;x<=(origin.getX()+46)>>4;x++)for(int z=origin.getZ()>>4;z<=(origin.getZ()+46)>>4;z++)w.setChunkForced(x,z,false);}h.succeed();});
    }
    static void biome(GameTestHelper h){var w=h.getLevel();try(var reader=w.getServer().getResourceManager().getResourceOrThrow(Identifier.fromNamespaceAndPath("tnd","dimension/vestige.json")).openAsReader()){
        var stem=net.minecraft.world.level.dimension.LevelStem.CODEC.parse(RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,w.registryAccess()),com.google.gson.JsonParser.parseReader(reader)).getOrThrow();var gen=stem.generator();var random=RandomState.create(w.registryAccess(),ResourceKey.create(Registries.NOISE_SETTINGS,Identifier.fromNamespaceAndPath("tnd","vestige")),91823);var r=CityRegions.region(-3,2);
        for(int x=-600;x<=600;x+=100)for(int z=-600;z<=600;z+=100)if(x*x+z*z<620*620){var p=new BlockPos(r.x()+x,100,r.z()+z);check(h,gen.getBiomeSource().getNoiseBiome(p.getX()>>2,25,p.getZ()>>2,random.sampler()).unwrapKey().orElseThrow().identifier().getPath().equals("neon_city"),"The entire 1280m region is a continuous native city biome");}
        for(int dx:new int[]{-400,0,400}){int height=gen.getBaseHeight(r.x()+dx,r.z(),Heightmap.Types.WORLD_SURFACE_WG,LevelHeightAccessor.create(0,256),random);check(h,height>=86&&height<=89,"Authored noise terrain aligns with the city plinth across a full kilometre");}
        check(h,r.roof(0)<255&&CityRegions.nearest(r.x(),r.z()).equals(r),"Dome fits dimension height; negative region coordinates preserve the unique lab identity");
    }catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}h.succeed();}
    static void city(GameTestHelper h){var w=FieldworkTests.vestige(h);var r=CityRegions.region(20,20);var feature=new MetropolisFeature();var origin=r.laboratory();var chunks=new ArrayList<ChunkPos>();for(int x=origin.getX()>>4;x<=(origin.getX()+46)>>4;x++)for(int z=origin.getZ()>>4;z<=(origin.getZ()+46)>>4;z++)chunks.add(new ChunkPos(x,z));Collections.shuffle(chunks,new Random(879));
        var outside=new BlockPos((origin.getX()&~15)-1,180,origin.getZ());w.setBlock(outside,Blocks.GOLD_BLOCK.defaultBlockState(),2);
        for(var cp:chunks){w.getChunk(cp.x(),cp.z());feature.generate(w,new BlockPos(cp.getMinBlockX(),0,cp.getMinBlockZ()),w.getRandom());}
        int computers=0;for(var cp:chunks)for(var be:w.getChunk(cp.x(),cp.z()).getBlockEntities().values())if(be instanceof IncubationComputerEntity)computers++;
        check(h,computers==1&&w.getBlockEntity(r.computer()) instanceof IncubationComputerEntity,"Random chunk visitation constructs one central laboratory and exactly one computer");var cp=new ChunkPos((r.x()+128)>>4,r.z()>>4);feature.generate(w,new BlockPos(cp.getMinBlockX(),0,cp.getMinBlockZ()),w.getRandom());check(h,w.getChunk(cp.x(),cp.z()).getBlockEntities().values().stream().noneMatch(b->b instanceof IncubationComputerEntity),"Neighbourhoods contain skyscrapers without another laboratory");check(h,w.getBlockState(outside).is(Blocks.GOLD_BLOCK),"Chunk-clipped generation preserves a neighbouring marker");h.succeed();}
    static void shield(GameTestHelper h){var w=FieldworkTests.vestige(h);var r=CityRegions.region(22,21);var at=new BlockPos(r.x(),120,r.z());FieldworkTests.platform(w,at);
        check(h,!CityRegions.protectedAt(w,at),"Old explored non-city chunks remain editable even under the new grid");
        for(int cx=(at.getX()-12)>>4;cx<=(at.getX()+12)>>4;cx++)for(int cz=(at.getZ()-12)>>4;cz<=(at.getZ()+12)>>4;cz++)w.getChunk(cx,cz).setData(CityRegions.GENERATED,true);
        var p=FieldworkTests.player(h,w,at);var chest=at.east(2);w.setBlock(chest,Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)w.getBlockEntity(chest)).setItem(0,new ItemStack(Items.DIAMOND,3));var stone=at.west(2);w.setBlock(stone,Blocks.STONE.defaultBlockState(),3);w.setBlock(at.south(2),Blocks.IRON_ORE.defaultBlockState(),3);
        try{check(h,!p.gameMode.destroyBlock(stone)&&w.getBlockState(stone).is(Blocks.STONE),"Native player mining cannot remove vanilla city blocks");p.setGameMode(GameType.CREATIVE);w.explode(null,at.getX()+.5,at.getY()+.5,at.getZ()+.5,4,Level.ExplosionInteraction.TNT);check(h,w.getBlockState(stone).is(Blocks.STONE)&&w.getBlockState(at.south(2)).is(Blocks.IRON_ORE)&&w.getBlockEntity(chest) instanceof ChestBlockEntity kept&&kept.getItem(0).getCount()==3,"A real TNT explosion preserves city stone, ores, chest and inventory");check(h,!p.gameMode.destroyBlock(chest),"Creative mode also respects the indestructible city");
        }finally{GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    static void piston(GameTestHelper h){var w=FieldworkTests.vestige(h);var r=CityRegions.region(23,20);var at=new BlockPos(r.x()+CityRegions.RADIUS+3,120,r.z());FieldworkTests.platform(w,at);w.getChunkAt(at).setData(CityRegions.GENERATED,true);w.getChunkAt(at.west()).setData(CityRegions.GENERATED,true);w.setBlock(at.west(),Blocks.STONE.defaultBlockState(),3);w.setBlock(at,Blocks.PISTON.defaultBlockState().setValue(PistonBaseBlock.FACING,Direction.WEST),3);w.setBlock(at.above(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);
        h.runAfterDelay(12,()->{try{check(h,w.getBlockState(at).is(Blocks.PISTON)&&!w.getBlockState(at).getValue(PistonBaseBlock.EXTENDED)&&w.getBlockState(at.west()).is(Blocks.STONE),"A real outside piston cannot push or pull through the city shield");}finally{FieldworkTests.release(w,at);}h.succeed();});}
    static void dome(GameTestHelper h){var w=h.getLevel();var at=h.absolutePos(new BlockPos(16,2,16));FieldworkTests.platform(w,at);w.setBlock(at,CityContent.DOME.get().defaultBlockState(),3);var p=GameplayTests.player(h);p.setPos(Vec3.atBottomCenterOf(at.west()));
        try{check(h,w.getBlockState(at).getCollisionShape(w,at).isEmpty()&&w.getBlockState(at).getDestroySpeed(w,at)<0,"Native dome block is unbreakable and has an empty collision shape");p.move(MoverType.SELF,new Vec3(2,0,0));check(h,p.getX()>at.getX()+1,"A native player physically walks through the force field");
        }finally{GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    private SymbiosisTests(){}
}
